// SignerSuite returns the checks of Signer, and the calls and the budgets
// of its callables.
func SignerSuite() conform.Suite[sign.Signer] {
	return conform.Suite[sign.Signer]{
		Declaration: "Signer",
		Package:     "go.thesmos.sh/core/crypto/sign",
		Generator:   conform.Generator{Name: "dokimi", Version: "0.1.0"},
		Checks: []conform.Check[sign.Signer]{
			{
				ID:          SignerChecks.Sign.Smoke(),
				Statement:   "Sign returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Apply: func(h *SignerHandle) {
					probe.Survives(h, func(ctx context.Context) error {
						_, err := h.Subject().Sign([]byte{1})
						return err
					})
				},
				Defect: signerSignPanics,
			},
			{
				ID:          SignerChecks.Sign.Smoke().Generated(),
				Statement:   "Sign returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.GeneratedInputs, spec.NothingBeyondACaller},
				Property: func(h *SignerHandle, c *prop.Case) {
					drawnMessage := c.Draw(prop.Of[[]byte](), "message")
					probe.Survives(h, func(ctx context.Context) error {
						_, err := h.Subject().Sign(drawnMessage)
						return err
					})
				},
				Defect: signerSignPanics,
			},
			{
				ID:          SignerChecks.KeyID.Smoke(),
				Statement:   "KeyID returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Apply: func(h *SignerHandle) {
					probe.Survives(h, func(ctx context.Context) error {
						h.Subject().KeyID()
						return nil
					})
				},
				Defect: signerKeyIDPanics,
			},
			{
				ID:          SignerChecks.KeyID.Deterministic(),
				Statement:   "KeyID returns the same value for the same inputs",
				Claim:       spec.Deterministic,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Entails:     []conform.ID[sign.Signer]{SignerChecks.KeyID.Smoke()},
				Apply: func(h *SignerHandle) {
					probe.RepeatAgrees(h, func(ctx context.Context) (sign.KeyID, error) {
						r0 := h.Subject().KeyID()
						return r0, nil
					})
				},
				Defect: signerKeyIDDrifts,
			},
			{
				ID:          SignerChecks.PublicKey.Smoke(),
				Statement:   "PublicKey returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Apply: func(h *SignerHandle) {
					probe.Survives(h, func(ctx context.Context) error {
						h.Subject().PublicKey()
						return nil
					})
				},
				Defect: signerPublicKeyPanics,
			},
			{
				ID:          SignerChecks.PublicKey.Deterministic(),
				Statement:   "PublicKey returns the same value for the same inputs",
				Claim:       spec.Deterministic,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Entails:     []conform.ID[sign.Signer]{SignerChecks.PublicKey.Smoke()},
				Apply: func(h *SignerHandle) {
					probe.RepeatAgrees(h, func(ctx context.Context) ([]byte, error) {
						r0 := h.Subject().PublicKey()
						return r0, nil
					})
				},
				Defect: signerPublicKeyDrifts,
			},
			{
				ID:          SignerChecks.Algorithm.Smoke(),
				Statement:   "Algorithm returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Apply: func(h *SignerHandle) {
					probe.Survives(h, func(ctx context.Context) error {
						h.Subject().Algorithm()
						return nil
					})
				},
				Defect: signerAlgorithmPanics,
			},
			{
				ID:          SignerChecks.Algorithm.Deterministic(),
				Statement:   "Algorithm returns the same value for the same inputs",
				Claim:       spec.Deterministic,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Entails:     []conform.ID[sign.Signer]{SignerChecks.Algorithm.Smoke()},
				Apply: func(h *SignerHandle) {
					probe.RepeatAgrees(h, func(ctx context.Context) (crypto.Algorithm, error) {
						r0 := h.Subject().Algorithm()
						return r0, nil
					})
				},
				Defect: signerAlgorithmDrifts,
			},
			{
				ID:          SignerChecks.Verify.Smoke(),
				Statement:   "Verify returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Apply: func(h *SignerHandle) {
					probe.Survives(h, func(ctx context.Context) error {
						h.Subject().Verify([]byte{1}, []byte{1})
						return nil
					})
				},
				Defect: signerVerifyPanics,
			},
			{
				ID:          SignerChecks.Verify.Smoke().Generated(),
				Statement:   "Verify returns without a panic for derived inputs",
				Claim:       spec.Smoke,
				Machineries: []spec.MachineryID{spec.GeneratedInputs, spec.NothingBeyondACaller},
				Property: func(h *SignerHandle, c *prop.Case) {
					drawnMessage := c.Draw(prop.Of[[]byte](), "message")
					drawnSignature := c.Draw(prop.Of[[]byte](), "signature")
					probe.Survives(h, func(ctx context.Context) error {
						h.Subject().Verify(drawnMessage, drawnSignature)
						return nil
					})
				},
				Defect: signerVerifyPanics,
			},
			{
				ID:          SignerChecks.Verify.Deterministic(),
				Statement:   "Verify returns the same value for the same inputs",
				Claim:       spec.Deterministic,
				Machineries: []spec.MachineryID{spec.NothingBeyondACaller},
				Shallow:     true,
				Entails:     []conform.ID[sign.Signer]{SignerChecks.Verify.Smoke()},
				Apply: func(h *SignerHandle) {
					probe.RepeatAgrees(h, func(ctx context.Context) (bool, error) {
						r0 := h.Subject().Verify([]byte{1}, []byte{1})
						return r0, nil
					})
				},
				Defect: signerVerifyDrifts,
			},
			{
				ID:          SignerChecks.Verify.Deterministic().Generated(),
				Statement:   "Verify returns the same value for the same inputs",
				Claim:       spec.Deterministic,
				Machineries: []spec.MachineryID{spec.GeneratedInputs, spec.NothingBeyondACaller},
				Entails:     []conform.ID[sign.Signer]{SignerChecks.Verify.Smoke().Generated()},
				Property: func(h *SignerHandle, c *prop.Case) {
					drawnMessage := c.Draw(prop.Of[[]byte](), "message")
					drawnSignature := c.Draw(prop.Of[[]byte](), "signature")
					probe.RepeatAgrees(h, func(ctx context.Context) (bool, error) {
						r0 := h.Subject().Verify(drawnMessage, drawnSignature)
						return r0, nil
					})
				},
				Defect: signerVerifyDrifts,
			},
			{
				ID:        SignerChecks.Sign.SignerSignaturesVerify(),
				Statement: "Verify accepts the signature of Sign over a message",
				Apply:     SignerSignaturesVerify,
				Defect:    signerSignsAnotherMessage,
			},
			{
				ID:        SignerChecks.Sign.SignerSignsAnEmptyMessage(),
				Statement: "Verify accepts the signature of Sign over a nil message, for a nil and for an empty message",
				Apply:     SignerSignsAnEmptyMessage,
				Defect:    signerRefusesAnEmptyMessage,
			},
			{
				ID:        SignerChecks.Verify.SignerRefusesAFlippedMessageBit(),
				Statement: "Verify refuses a signature of Sign for its message with the first bit changed",
				Apply:     SignerRefusesAFlippedMessageBit,
				Defect:    signerRestoresTheFirstMessageByte,
			},
			{
				ID:        SignerChecks.Verify.SignerRefusesAFlippedSignatureBit(),
				Statement: "Verify refuses a signature of Sign whose first bit changed",
				Apply:     SignerRefusesAFlippedSignatureBit,
				Defect:    signerRestoresTheFirstSignatureByte,
			},
			{
				ID:        SignerChecks.Verify.SignerRefusesASignatureOfAWrongLength(),
				Statement: "Verify refuses a nil, an empty, a 1-byte and a 16-byte signature",
				Apply:     SignerRefusesASignatureOfAWrongLength,
				Defect:    signerAcceptsANilSignature,
			},
		},
		Calls: []conform.Call[sign.Signer]{
			{
				Calls:    signerSignCalls,
				Over:     newSignerOver,
				Callable: SignerChecks.Sign.Callable,
			},
			{
				Calls:    signerKeyIDCalls,
				Over:     newSignerOver,
				Callable: SignerChecks.KeyID.Callable,
			},
			{
				Calls:    signerPublicKeyCalls,
				Over:     newSignerOver,
				Callable: SignerChecks.PublicKey.Callable,
			},
			{
				Calls:    signerAlgorithmCalls,
				Over:     newSignerOver,
				Callable: SignerChecks.Algorithm.Callable,
			},
			{
				Calls:    signerVerifyCalls,
				Over:     newSignerOver,
				Callable: SignerChecks.Verify.Callable,
			},
		},
	}
}

// RunSignerSuite applies the checks of Signer, and the checks that opts
// add, to a fresh subject of newSubject for each check.
func RunSignerSuite[T sign.Signer](t *testing.T, newSubject func() T, opts ...SignerOption) {
	t.Helper()
	RunSignerSuiteFromHandle(t, func(*SignerHandle) T { return newSubject() }, opts...)
}

// RunSignerSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunSignerSuiteFromHandle[T sign.Signer](t *testing.T, newSubject func(h *SignerHandle) T, opts ...SignerOption) {
	t.Helper()
	conform.Run(t, SignerSuite(), signerSubjects(newSubject), opts...)
}

// FuzzSignerSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzSignerSuite[T sign.Signer](
	f *testing.F,
	callable conform.Callable[sign.Signer],
	newSubject func(h *SignerHandle) T,
	opts ...SignerOption,
) {
	f.Helper()
	conform.Fuzz(f, SignerSuite(), callable, signerSubjects(newSubject), opts...)
}

// RunSignerBudgets applies the allocation ceilings of Signer and its
// checks that count allocations, and the ceilings and the checks that opts
// add, to a fresh subject of newSubject for each case.
func RunSignerBudgets[T sign.Signer](t *testing.T, newSubject func(h *SignerHandle) T, opts ...SignerOption) {
	t.Helper()
	conform.RunBudgets(t, SignerSuite(), signerSubjects(newSubject), opts...)
}

// BenchSignerSuite measures callable on a subject of newSubject, under the
// ceilings of its budget.
func BenchSignerSuite[T sign.Signer](
	b conform.B,
	callable conform.Callable[sign.Signer],
	newSubject func(h *SignerHandle) T,
	opts ...SignerOption,
) {
	b.Helper()
	conform.Bench(b, SignerSuite(), callable, signerSubjects(newSubject), opts...)
}

// signerSubjects returns the factory of the subjects of Signer that calls
// newSubject with the handle of each check.
func signerSubjects[T sign.Signer](newSubject func(h *SignerHandle) T) func(h *SignerHandle) sign.Signer {
	return func(h *SignerHandle) sign.Signer { return newSubject(h) }
}

// signerSignCalls generates the calls of Signer.Sign with the inputs that
// each case draws.
var signerSignCalls = prop.Composite(func(c *prop.Case) func(context.Context, sign.Signer) error {
	message := c.Draw(prop.Of[[]byte](), "message")
	return func(_ context.Context, subject sign.Signer) error {
		_, err := subject.Sign(message)
		return err
	}
})

