// RunStreamingSignerSuite applies the checks of StreamingSigner, and the
// checks that opts add, to a fresh subject of newSubject for each check.
func RunStreamingSignerSuite[T sign.StreamingSigner](t *testing.T, newSubject func() T, opts ...StreamingSignerOption) {
	t.Helper()
	RunStreamingSignerSuiteFromHandle(t, func(*StreamingSignerHandle) T { return newSubject() }, opts...)
}

// RunStreamingSignerSuiteFromHandle applies the same checks to a subject
// that newSubject builds from the handle of each check.
func RunStreamingSignerSuiteFromHandle[T sign.StreamingSigner](
	t *testing.T,
	newSubject func(h *StreamingSignerHandle) T,
	opts ...StreamingSignerOption,
) {
	t.Helper()
	conform.Run(t, StreamingSignerSuite(), streamingSignerSubjects(newSubject), opts...)
}

// FuzzStreamingSignerSuite registers on f the fuzz target of the property
// checks of callable, on a subject that newSubject builds from the handle
// of each case.
func FuzzStreamingSignerSuite[T sign.StreamingSigner](
	f *testing.F,
	callable conform.Callable[sign.StreamingSigner],
	newSubject func(h *StreamingSignerHandle) T,
	opts ...StreamingSignerOption,
) {
	f.Helper()
	conform.Fuzz(f, StreamingSignerSuite(), callable, streamingSignerSubjects(newSubject), opts...)
}

// RunStreamingSignerBudgets applies the allocation ceilings of
// StreamingSigner and its checks that count allocations, and the ceilings
// and the checks that opts add, to a fresh subject of newSubject for each
// case.
func RunStreamingSignerBudgets[T sign.StreamingSigner](
	t *testing.T,
	newSubject func(h *StreamingSignerHandle) T,
	opts ...StreamingSignerOption,
) {
	t.Helper()
	conform.RunBudgets(t, StreamingSignerSuite(), streamingSignerSubjects(newSubject), opts...)
}

// BenchStreamingSignerSuite measures callable on a subject of newSubject,
// under the ceilings of its budget.
func BenchStreamingSignerSuite[T sign.StreamingSigner](
	b conform.B,
	callable conform.Callable[sign.StreamingSigner],
	newSubject func(h *StreamingSignerHandle) T,
	opts ...StreamingSignerOption,
) {
	b.Helper()
	conform.Bench(b, StreamingSignerSuite(), callable, streamingSignerSubjects(newSubject), opts...)
}

// streamingSignerSubjects returns the factory of the subjects of
// StreamingSigner that calls newSubject with the handle of each check.
func streamingSignerSubjects[T sign.StreamingSigner](
	newSubject func(h *StreamingSignerHandle) T,
) func(h *StreamingSignerHandle) sign.StreamingSigner {
	return func(h *StreamingSignerHandle) sign.StreamingSigner { return newSubject(h) }
}

