// streamingSignerOverEmbedded is sign.StreamingSigner under the name of
// the field that streamingSignerOver embeds.
type streamingSignerOverEmbedded = sign.StreamingSigner

// streamingSignerOver is a subject of StreamingSigner whose callables call
// spend and return their zero results. The planted defect of a ceiling
// passes a spend that exceeds the ceiling.
type streamingSignerOver struct {
	streamingSignerOverEmbedded
	spend func()
}

// NewSignStream calls spend and returns its zero results.
func (o streamingSignerOver) NewSignStream() (r0 sign.SignStream) {
	o.spend()
	return r0
}

// Sign calls spend and returns its zero results.
func (o streamingSignerOver) Sign([]byte) (r0 []byte, r1 error) {
	o.spend()
	return r0, r1
}

// KeyID calls spend and returns its zero results.
func (o streamingSignerOver) KeyID() (r0 sign.KeyID) {
	o.spend()
	return r0
}

// PublicKey calls spend and returns its zero results.
func (o streamingSignerOver) PublicKey() (r0 []byte) {
	o.spend()
	return r0
}

// Algorithm calls spend and returns its zero results.
func (o streamingSignerOver) Algorithm() (r0 crypto.Algorithm) {
	o.spend()
	return r0
}

// Verify calls spend and returns its zero results.
func (o streamingSignerOver) Verify([]byte, []byte) (r0 bool) {
	o.spend()
	return r0
}

// newStreamingSignerOver returns the planted defect of a ceiling of
// StreamingSigner, whose callables call spend.
func newStreamingSignerOver(_ *StreamingSignerHandle, spend func()) sign.StreamingSigner {
	return streamingSignerOver{spend: spend}
}

