// RunStreamingVerifierSuite applies the checks of StreamingVerifier, and
// the checks that opts add, to a fresh subject of newSubject for each
// check.
func RunStreamingVerifierSuite[T sign.StreamingVerifier](
	t *testing.T,
	newSubject func() T,
	opts ...StreamingVerifierOption,
) {
	t.Helper()
	RunStreamingVerifierSuiteFromHandle(t, func(*StreamingVerifierHandle) T { return newSubject() }, opts...)
}

// RunStreamingVerifierSuiteFromHandle applies the same checks to a subject
// that newSubject builds from the handle of each check.
func RunStreamingVerifierSuiteFromHandle[T sign.StreamingVerifier](
	t *testing.T,
	newSubject func(h *StreamingVerifierHandle) T,
	opts ...StreamingVerifierOption,
) {
	t.Helper()
	conform.Run(t, StreamingVerifierSuite(), streamingVerifierSubjects(newSubject), opts...)
}

// FuzzStreamingVerifierSuite registers on f the fuzz target of the
// property checks of callable, on a subject that newSubject builds from
// the handle of each case.
func FuzzStreamingVerifierSuite[T sign.StreamingVerifier](
	f *testing.F,
	callable conform.Callable[sign.StreamingVerifier],
	newSubject func(h *StreamingVerifierHandle) T,
	opts ...StreamingVerifierOption,
) {
	f.Helper()
	conform.Fuzz(f, StreamingVerifierSuite(), callable, streamingVerifierSubjects(newSubject), opts...)
}

// RunStreamingVerifierBudgets applies the allocation ceilings of
// StreamingVerifier and its checks that count allocations, and the
// ceilings and the checks that opts add, to a fresh subject of newSubject
// for each case.
func RunStreamingVerifierBudgets[T sign.StreamingVerifier](
	t *testing.T,
	newSubject func(h *StreamingVerifierHandle) T,
	opts ...StreamingVerifierOption,
) {
	t.Helper()
	conform.RunBudgets(t, StreamingVerifierSuite(), streamingVerifierSubjects(newSubject), opts...)
}

// BenchStreamingVerifierSuite measures callable on a subject of
// newSubject, under the ceilings of its budget.
func BenchStreamingVerifierSuite[T sign.StreamingVerifier](
	b conform.B,
	callable conform.Callable[sign.StreamingVerifier],
	newSubject func(h *StreamingVerifierHandle) T,
	opts ...StreamingVerifierOption,
) {
	b.Helper()
	conform.Bench(b, StreamingVerifierSuite(), callable, streamingVerifierSubjects(newSubject), opts...)
}

// streamingVerifierSubjects returns the factory of the subjects of
// StreamingVerifier that calls newSubject with the handle of each check.
func streamingVerifierSubjects[T sign.StreamingVerifier](
	newSubject func(h *StreamingVerifierHandle) T,
) func(h *StreamingVerifierHandle) sign.StreamingVerifier {
	return func(h *StreamingVerifierHandle) sign.StreamingVerifier { return newSubject(h) }
}

